/* Operator 40 service worker — offline-first PWA.
   Same-origin assets are hashed by Vite (immutable) so cache-first is safe;
   navigations are network-first with the cached shell as offline fallback. */

const CACHE = 'o40-v58e52d6e';

// Clip critici per le prime 3 missioni + pancia — precache per offline immediato (~14M, non blocca install se fallisce)
const PRECACHE_CLIPS = [
  './clips/squat.mp4',
  './clips/flessioni.mp4',
  './clips/deadbug.mp4',
  './clips/ponte.mp4',
  './clips/wallsit.mp4',
  './clips/superman.mp4',
];
// Offline MediaPipe WASM+model — precached if present (generated by npm run fetch:mediapipe, gitignored)
const PRECACHE_MEDIAPIPE = [
  './wasm/wasm_internal.js',
  './wasm/wasm_nosimd_internal.js',
  './models/pose_landmarker_lite.task',
];

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE).then(async (c) => {
      await c.addAll(['./index.html']);
      // precache clip critici + mediapipe offline (best-effort) — non faila install
      await Promise.allSettled([...PRECACHE_CLIPS, ...PRECACHE_MEDIAPIPE].map((url) => c.add(url).catch(() => {})));
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

/* ---- Push: mostra notifica anche con PWA chiusa ---- */
self.addEventListener('push', (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = { title: event.data ? event.data.text() : '', body: '' };
  }
  const title = data.title || 'Operator 40 — Missione pronta';
  const options = {
    body: data.body || 'La tua missione di 15 min ti aspetta. Andiamo!',
    icon: './icons/icon-192.png',
    badge: './icons/icon-192.png',
    tag: data.tag || 'o40-push',
    data: { url: data.url || './' },
    requireInteraction: false,
  };
  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = event.notification.data && event.notification.data.url ? event.notification.data.url : './';
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((list) => {
      for (const c of list) {
        if (c.url.includes('operator40') && 'focus' in c) return c.focus();
      }
      if (clients.openWindow) return clients.openWindow(url);
    })
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // Navigations: network first, fall back to the cached shell (offline).
  if (req.mode === 'navigate') {
    event.respondWith(
      fetch(req)
        .then((res) => {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put('./index.html', copy));
          return res;
        })
        .catch(() => caches.match('./index.html'))
    );
    return;
  }

    // Same-origin assets: cache first, then network (and cache the result).
  // Bypass cache for Vite HMR / dev server and for range requests (audio).
  if (req.headers.has('range')) return;
  event.respondWith(
    caches.match(req).then((cached) => {
      if (cached) return cached;
      return fetch(req).then((res) => {
        // Only cache successful, non-opaque, non-range responses
        if (res && res.ok && res.type !== 'opaque') {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put(req, copy));
        }
        return res;
      }).catch(() => caches.match(req));
    })
  );
});